#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;
extern "C" {
int sample(double* nodes,int N,double step,double* out){
 int count=0;
 for(int i=0;i<N-1;i++){
  double *a=nodes+3*i,*b=a+3,*prev=nodes+3*max(0,i-1),*nxt=nodes+3*min(N-1,i+2);
  double dist=hypot(b[0]-a[0],b[1]-a[1]);int n=max(2,int(dist/step)+1);
  for(int j=0;j<n;j++) {double t=double(j)/n,t2=t*t,t3=t2*t;
   for(int d=0;d<3;d++){
    double m0=i>0?(b[d]-prev[d])*.5:b[d]-a[d],m1=i+2<N?(nxt[d]-a[d])*.5:b[d]-a[d];
    out[count*3+d]=(2*t3-3*t2+1)*a[d]+(t3-2*t2+t)*m0+(-2*t3+3*t2)*b[d]+(t3-t2)*m1;
   }out[count*3+2]=max(.1,out[count*3+2]);count++;
  }
 }
 for(int d=0;d<3;d++)out[count*3+d]=nodes[3*(N-1)+d];return count+1;
}
void render(double* nodes,int N,int x0,int y0,int x1,int y1,unsigned char* mask){
 int h=y1-y0,wid=x1-x0;fill(mask,mask+h*wid,0);
 double pts[30000];int count=sample(nodes,N,1.,pts);
 for(int k=0;k<count;k++){
  double x=pts[3*k],y=pts[3*k+1],w=max(.1,pts[3*k+2]);int k0=max(0,k-1),k1=min(count-1,k+1);
  double dx=pts[3*k1]-pts[3*k0],dy=pts[3*k1+1]-pts[3*k0+1],L=max(1e-8,hypot(dx,dy));dx/=L;dy/=L;
  double dep=(w*.2218598696+.3)/1.187,d=(1.38+1.075*dep)/.2218598696;
  int r=int(w/2+d+2);
  for(int v=max(y0,int(y)-r);v<min(y1,int(y)+r+1);v++)for(int u=max(x0,int(x)-r);u<min(x1,int(x)+r+1);u++){
   double ax=u-x,ay=v-y,s=-(ax*dx+ay*dy),t=-ax*dy+ay*dx;
   if(s>=0 && s<=d*(1-4*t*t/(w*w)))mask[(v-y0)*wid+u-x0]=1;
  }
 }
}
double cost(double*nodes,int N,double*weight,int*xbox,double*initial){
 int size=(xbox[2]-xbox[0])*(xbox[3]-xbox[1]);vector<unsigned char> mask(size);render(nodes,N,xbox[0],xbox[1],xbox[2],xbox[3],mask.data());
 double loss=0;for(int k=0;k<size;k++)if(mask[k])loss+=weight[k];
 for(int i=0;i<N;i++)for(int d=0;d<2;d++){double dif=nodes[i*3+d]-initial[i*3+d];loss+=.025*dif*dif;}return loss;
}
double descend(double*nodes,int N,double*weight,int*box,double*initial,double delta,int rounds){
 double best=cost(nodes,N,weight,box,initial);
 for(int it=0;it<rounds;it++){
  bool improved=false;
  for(int i=0;i<N;i++)for(int d=0;d<3;d++){
   int idx=i*3+d;double old=nodes[idx],nv=old;
   for(double sign:{-1.,1.}){double val=old+sign*delta;
    if(d==2&&(val<.3||val>65))continue;
    if(d<2&&abs(val-initial[idx])>18)continue;
    nodes[idx]=val;double c=cost(nodes,N,weight,box,initial);
    if(c<best-.02){best=c;nv=val;improved=true;}
   }nodes[idx]=nv;
  }if(!improved)break;
 }return best;
}
}
